def svg(name, cls=''):
    d = P[name]
    return ('<svg%s viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" '
            'stroke-linejoin="round" aria-hidden="true"><path d="%s"/></svg>') % (' class="%s"' % cls if cls else '', d)


